#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>

#if defined(__SSE2__)
#include <emmintrin.h>
#endif

constexpr double PI = 3.141592653589793;
constexpr double SOLAR_MASS = 4.0 * PI * PI;
constexpr double DAYS_PER_YEAR = 365.24;
constexpr double DT = 0.01;

struct Body {
    double x, y, z;
    double vx, vy, vz;
    double mass;
};

static void offset_momentum(Body* bodies) {
    double px = 0.0;
    double py = 0.0;
    double pz = 0.0;

    for (int i = 0; i < 5; ++i) {
        px += bodies[i].vx * bodies[i].mass;
        py += bodies[i].vy * bodies[i].mass;
        pz += bodies[i].vz * bodies[i].mass;
    }

    bodies[0].vx = -px / SOLAR_MASS;
    bodies[0].vy = -py / SOLAR_MASS;
    bodies[0].vz = -pz / SOLAR_MASS;
}

static double energy(const Body* bodies) {
    double result = 0.0;

    for (int i = 0; i < 5; ++i) {
        const Body& a = bodies[i];
        result += 0.5 * a.mass *
                  (a.vx * a.vx + a.vy * a.vy + a.vz * a.vz);

        for (int j = i + 1; j < 5; ++j) {
            const Body& b = bodies[j];
            const double dx = a.x - b.x;
            const double dy = a.y - b.y;
            const double dz = a.z - b.z;
            const double distance = std::sqrt(dx * dx + dy * dy + dz * dz);
            result -= (a.mass * b.mass) / distance;
        }
    }

    return result;
}

static void simulate(Body* bodies, std::uint64_t steps) {
    alignas(16) double dx[10];
    alignas(16) double dy[10];
    alignas(16) double dz[10];
    alignas(16) double magnitude[10];

#if defined(__SSE2__)
    const __m128d dt = _mm_set1_pd(DT);
#endif

    for (std::uint64_t step = 0; step < steps; ++step) {
        int pair = 0;
        for (int i = 0; i < 4; ++i) {
            for (int j = i + 1; j < 5; ++j, ++pair) {
                dx[pair] = bodies[i].x - bodies[j].x;
                dy[pair] = bodies[i].y - bodies[j].y;
                dz[pair] = bodies[i].z - bodies[j].z;
            }
        }

#if defined(__SSE2__)
        for (int k = 0; k < 10; k += 2) {
            const __m128d x = _mm_load_pd(dx + k);
            const __m128d y = _mm_load_pd(dy + k);
            const __m128d z = _mm_load_pd(dz + k);

            const __m128d distance_squared = _mm_add_pd(
                _mm_add_pd(_mm_mul_pd(x, x), _mm_mul_pd(y, y)),
                _mm_mul_pd(z, z));

            const __m128d denominator = _mm_mul_pd(
                distance_squared, _mm_sqrt_pd(distance_squared));

            _mm_store_pd(magnitude + k, _mm_div_pd(dt, denominator));
        }
#else
        for (int k = 0; k < 10; ++k) {
            const double distance_squared =
                dx[k] * dx[k] + dy[k] * dy[k] + dz[k] * dz[k];
            magnitude[k] =
                DT / (distance_squared * std::sqrt(distance_squared));
        }
#endif

        pair = 0;
        for (int i = 0; i < 4; ++i) {
            double vx = bodies[i].vx;
            double vy = bodies[i].vy;
            double vz = bodies[i].vz;
            const double mass = bodies[i].mass;

            for (int j = i + 1; j < 5; ++j, ++pair) {
                const double scale_i = bodies[j].mass * magnitude[pair];
                const double scale_j = mass * magnitude[pair];

                vx -= dx[pair] * scale_i;
                vy -= dy[pair] * scale_i;
                vz -= dz[pair] * scale_i;

                bodies[j].vx += dx[pair] * scale_j;
                bodies[j].vy += dy[pair] * scale_j;
                bodies[j].vz += dz[pair] * scale_j;
            }

            bodies[i].vx = vx;
            bodies[i].vy = vy;
            bodies[i].vz = vz;
        }

        for (int i = 0; i < 5; ++i) {
            bodies[i].x += DT * bodies[i].vx;
            bodies[i].y += DT * bodies[i].vy;
            bodies[i].z += DT * bodies[i].vz;
        }
    }
}

